// 箭头函数示例

// 传统函数
function add(a, b) {
    return a + b;
}

// 箭头函数
const addArrow = (a, b) => a + b;

console.log('传统函数:', add(5, 3));
console.log('箭头函数:', addArrow(5, 3));

// 单个参数可以省略括号
const square = x => x * x;
console.log('平方:', square(4));

// 多行箭头函数
const calculate = (a, b) => {
    const sum = a + b;
    const product = a * b;
    return { sum, product };
};

console.log('计算结果:', calculate(3, 4));

// 在数组方法中使用
const numbers = [1, 2, 3, 4, 5];
const squares = numbers.map(n => n * n);
console.log('平方数组:', squares);

// this绑定的差异
const obj = {
    name: '测试对象',
    traditional: function() {
        setTimeout(function() {
            console.log('传统函数this:', this.name); // undefined
        }, 100);
    },
    arrow: function() {
        setTimeout(() => {
            console.log('箭头函数this:', this.name); // '测试对象'
        }, 100);
    }
};

