destructuring.code:
// 解构赋值示例

// 数组解构
const colors = ['red', 'green', 'blue'];
const [firstColor, secondColor, thirdColor] = colors;
console.log('第一个颜色:', firstColor);
console.log('第二个颜色:', secondColor);

// 对象解构
const user = {
    name: '张三',
    age: 25,
    city: '北京',
    skills: ['JavaScript', 'HTML', 'CSS']
};

const { name, age, city } = user;
console.log(`姓名: ${name}, 年龄: ${age}, 城市: ${city}`);

// 重命名解构
const { name: userName, age: userAge } = user;
console.log('用户名:', userName);

// 默认值
const { country = '中国' } = user;
console.log('国家:', country);

// 嵌套解构
const company = {
    name: '科技公司',
    address: {
        street: '科技园路',
        city: '深圳',
        zipcode: '518000'
    }
};

const { address: { city: companyCity } } = company;
console.log('公司城市:', companyCity);

// 函数参数解构
function printUser({ name, age }) {
    console.log(`用户: ${name}, 年龄: ${age}`);
}

printUser(user);

// 数组剩余元素
const [first, ...restColors] = colors;
console.log('剩余颜色:', restColors);
